style.css:
@-moz-document url-prefix("http"), url-prefix("https") {
/* ---------- Main Text Elements ---------- */
    body, p, span, li, a, h1, h2, h3, h4, h5, h6 {
        font-family: 'Minecraft', sans-serif !important;
        font-size: 16px !important;
        line-height: 1.5 !important;
        color: #f0f0f0 !important; /* light text for dark background */
    }

    /* ---------- Background ---------- */
    body {
        background-color: #1a1a1a !important; /* dark gray/black */
    }

    /* ---------- Links ---------- */
    a {
        color: #00ff00 !important; /* Minecraft green */
        text-decoration: none !important;
    }
    a:hover {
        text-decoration: underline !important;
    }

    /* ---------- Headings ---------- */
    h1, h2, h3, h4, h5, h6 {
        font-family: 'Minecraft', sans-serif !important;
        color: #ffffff !important;
    }

    /* ---------- Buttons & Inputs ---------- */
    button, input, textarea {
        font-family: 'Minecraft', sans-serif !important;
        color: #f0f0f0 !important;
        background-color: #2e2e2e !important;
        border: 1px solid #00ff00 !important;
    }

    /* ---------- Lists ---------- */
    ul, ol, li {
        font-family: 'Minecraft', sans-serif !important;
    }

    /* ---------- Optional Scrollbar Styling ---------- */
    ::-webkit-scrollbar {
        width: 12px;
        background-color: #1a1a1a;
    }
    ::-webkit-scrollbar-thumb {
        background-color: #00ff00;
        border-radius: 6px;
    }
}

@-moz-document url-prefix("http"), url-prefix("https") {
/* Background and main text */
    body, p, span, li, a, h1, h2, h3, h4, h5, h6 {
        background-color: #1a1a1a !important; /* dark background */
        color: #f0f0f0 !important;            /* light text */
    }

    /* Links */
    a {
        color: #00aaff !important;            /* bright blue links */
        text-decoration: none !important;
    }
    a:hover {
        text-decoration: underline !important;
    }

    /* Buttons and inputs */
    button, input, textarea {
        background-color: #2e2e2e !important;
        color: #f0f0f0 !important;
        border: 1px solid #444 !important;
    }
}

@-moz-document url-prefix("http"), url-prefix("https") {
body::after {
        content: "";
        position: fixed;
        bottom: 20px;
        right: 20px;
        width: 100px;
        height: 100px;
        background-image: url('https://upload.wikimedia.org/wikipedia/commons/5/51/Minecraft_creeper.png');
        background-size: contain;
        background-repeat: no-repeat;
        z-index: 9999;
        pointer-events: none; /* allows clicking through */
        opacity: 0.7; /* subtle */
    }
}
